import { useEffect, useMemo, useRef, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import {
  Eye, EyeOff, Activity, ArrowDownLeft, ArrowDownRight, ArrowLeftRight, ArrowRight,
  ArrowUpRight, Bell, BookOpen, CalendarDays, Check, CheckCircle2,
  ChevronDown, ChevronRight, CircleAlert, CircleDollarSign, CreditCard,
  Download, FileClock, HandCoins, Landmark, LayoutDashboard, Menu,
  MoreHorizontal, Pencil, PiggyBank, Plus, ReceiptText, Search,
  Settings2, ShieldCheck, Sparkles, Target, Trash2, TrendingDown,
  Upload, Wallet, X, Link2, NotebookPen
} from 'lucide-react';
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import type { Debt, DebtKind, EntryType, FinanceData, Transaction } from './types';
import { DEBT_KINDS, EMPTY_DATA, EXPENSE_CATEGORIES, INCOME_CATEGORIES } from './types';
import { addMonths, dateLabel, daysUntil, debtOrder, dueDate, forecast, lastMonths, localISO, money, monthStats, shortMoney, spendByCategory, thisMonth, total } from './finance';
import { exportData, parseData } from './storage';
import RolloverPage from './RolloverPage';
import AgentPage from './AgentPage';
import MCPPage from './MCPPage';
import SpendingCoachPage from './SpendingCoachPage';
